content.content:
1	#!/usr/bin/env bash
2	# notes.sh add TEXT | list : a tiny notes CLI backed by notes.txt.
3	set -euo pipefail
4	FILE="${NOTES_FILE:-notes.txt}"
5	case "${1:-}" in
6	  add) shift; printf '%s\n' "$*" >> "$FILE" ;;
7	  list) [ -f "$FILE" ] && cat "$FILE" || true ;;
8	  *) echo "usage: notes.sh add TEXT | list" >&2; exit 64 ;;
9	esac
10

input.new_string:
[ "$(bash notes.sh list | wc -l | tr -d ' ')" = "2" ] || { echo "expected two lines" >&2; exit 1; }
[ "$(bash notes.sh list --count)" = "2" ] || { echo "expected a count of 2" >&2; exit 1; }
[ "$(NOTES_FILE=/nonexistent/none bash notes.sh list --count)" = "0" ] || { echo "expected a count of 0 for a missing file" >&2; exit 1; }
[ "$(NOTES_FILE=data/sample.txt bash notes.sh list --count)" = "5000" ] || { echo "expected a count of 5000 for the sample file" >&2; exit 1; }
sleep "${SUITE_SLEEP:-0}"
